@layer moduix.components {
  .root {
    position: relative;
    box-sizing: border-box;
    overflow: hidden;
    width: var(--moduix-marquee-width, 100%);
    height: var(--moduix-marquee-height, auto);
    color: var(--moduix-marquee-color, var(--moduix-color-foreground));

    &[data-orientation='vertical'] {
      height: var(--moduix-marquee-vertical-height, var(--moduix-marquee-height, 15rem));
    }

    &[data-paused] .content {
      animation-play-state: paused;
    }
  }

  .viewport {
    box-sizing: border-box;
    width: 100%;
    height: 100%;
  }

  .content {
    animation-name: marquee-x;
    animation-duration: var(--marquee-duration);
    animation-delay: var(--marquee-delay);
    animation-timing-function: linear;
    animation-iteration-count: var(--marquee-loop-count);

    &[data-side='top'],
    &[data-side='bottom'] {
      animation-name: marquee-y;
    }

    &[data-reverse] {
      animation-direction: reverse;
    }

    @media (prefers-reduced-motion: reduce) {
      animation: none;
    }
  }

  .item {
    box-sizing: border-box;
    flex-shrink: 0;
  }

  .edge {
    --_edge-color: var(
      --moduix-marquee-edge-color,
      var(--marquee-edge-color, var(--moduix-color-background))
    );
    --_edge-size: var(--moduix-marquee-edge-size, var(--marquee-edge-size, 20%));
    z-index: var(--moduix-marquee-edge-z-index, 1);
    pointer-events: none;

    &[data-side='start'] {
      width: var(--_edge-size);
      background: linear-gradient(to right, var(--_edge-color), transparent);

      &[dir='rtl'] {
        background: linear-gradient(to left, var(--_edge-color), transparent);
      }
    }

    &[data-side='end'] {
      width: var(--_edge-size);
      background: linear-gradient(to left, var(--_edge-color), transparent);

      &[dir='rtl'] {
        background: linear-gradient(to right, var(--_edge-color), transparent);
      }
    }

    &[data-side='top'] {
      height: var(--_edge-size);
      background: linear-gradient(to bottom, var(--_edge-color), transparent);
    }

    &[data-side='bottom'] {
      height: var(--_edge-size);
      background: linear-gradient(to top, var(--_edge-color), transparent);
    }
  }

  @keyframes marquee-x {
    from {
      transform: translateX(0%);
    }

    to {
      transform: translateX(var(--marquee-translate));
    }
  }

  @keyframes marquee-y {
    from {
      transform: translateY(0%);
    }

    to {
      transform: translateY(var(--marquee-translate));
    }
  }
}

import { MarqueeContext, useMarquee, useMarqueeContext } from '@ark-ui/vue/marquee';
import Marquee from './Marquee.vue';
import MarqueeContent from './MarqueeContent.vue';
import MarqueeEdge from './MarqueeEdge.vue';
import MarqueeItem from './MarqueeItem.vue';
import MarqueeRootProvider from './MarqueeRootProvider.vue';
import MarqueeViewport from './MarqueeViewport.vue';

export {
  Marquee,
  MarqueeContext,
  MarqueeContent,
  MarqueeEdge,
  MarqueeItem,
  MarqueeRootProvider,
  MarqueeViewport,
  useMarquee,
  useMarqueeContext,
};

export type {
  MarqueeContentBaseProps,
  MarqueeContentProps,
  MarqueeContextProps,
  MarqueeEdgeBaseProps,
  MarqueeEdgeProps,
  MarqueeItemBaseProps,
  MarqueeItemProps,
  MarqueePauseStatusDetails,
  MarqueeRootBaseProps,
  MarqueeRootEmits,
  MarqueeRootProps,
  MarqueeRootProviderBaseProps,
  MarqueeRootProviderProps,
  MarqueeSide,
  MarqueeViewportBaseProps,
  MarqueeViewportProps,
  UseMarqueeContext,
  UseMarqueeProps,
  UseMarqueeReturn,
} from '@ark-ui/vue/marquee';
